import variants from "../content/image-variants.json";

type Variant = { w: number; src: string };

const LOCAL_VARIANTS = variants as Record<string, Variant[]>;
const SANITY_CDN = "https://cdn.sanity.io/";
const SANITY_WIDTHS = [480, 960, 1600];

/**
 * Returns src/srcSet for a site image. Local photos use the WebP variants
 * generated by `npm run images`; Sanity photos use the CDN's resizing.
 */
export function responsiveImage(src: string): { src: string; srcSet?: string } {
  const local = LOCAL_VARIANTS[src];
  if (local?.length) {
    return {
      src: local[Math.min(1, local.length - 1)].src,
      srcSet: local.map((v) => `${v.src} ${v.w}w`).join(", "),
    };
  }

  if (src.startsWith(SANITY_CDN)) {
    const sized = (w: number) => `${src}?w=${w}&fit=max&auto=format`;
    return {
      src: sized(960),
      srcSet: SANITY_WIDTHS.map((w) => `${sized(w)} ${w}w`).join(", "),
    };
  }

  return { src };
}

/** Largest available version, used by the gallery viewer. */
export function largestImage(src: string): string {
  const local = LOCAL_VARIANTS[src];
  if (local?.length) return local[local.length - 1].src;
  if (src.startsWith(SANITY_CDN)) return `${src}?w=1600&fit=max&auto=format`;
  return src;
}
